-- when you backfill data ,if your old data is not null but your new data is null,it will do not update,so you need to rm hdfs file
create temporary view user_dwm_${grass_region_without_quote} as
SELECT
     local_date
    ,user_id
    ,array_union(array_union(scenario_tags, COALESCE(source1_scenario_tags, array())), COALESCE(source2_scenario_tags, array())) AS union_scenario_tags
FROM srdi_mart.dwm_sr_data_warehouse_platform_user_item
WHERE grass_region = ${grass_region} AND local_date BETWEEN date_sub(${local_date}, 30) AND ${local_date}
AND operation IN ('order') and order_cnt > 0
GROUP BY
     local_date
    ,user_id
    ,union_scenario_tags
;
--sql_divide_splitter--

create temporary view explode_data_${grass_region_without_quote} as
SELECT
     user_id
    ,if(grouping(scenario_tag)=1,'__ALL__',scenario_tag) as scenario_tag
    ,sum(if(local_date between date_add(${local_date},-6) and ${local_date},1,0)) as order_a6_a0
    ,sum(if(local_date between date_add(${local_date},-29) and ${local_date},1,0)) as order_a29_a0
    ,sum(if(local_date = date_add(${local_date},-7) ,1,0)) as order_a7
    ,sum(if(local_date = date_add(${local_date},-30),1,0)) as order_a30
FROM user_dwm_${grass_region_without_quote}
LATERAL VIEW EXPLODE(union_scenario_tags) AS scenario_tag
GROUP BY
     user_id
    ,scenario_tag
GROUPING SETS ((user_id,scenario_tag),(user_id))
;
--sql_divide_splitter--

CACHE TABLE result_${grass_region_without_quote} as (
    SELECT
         scenario_tag
        ,count(if(order_a7>0 and order_a6_a0>0,user_id,null))/count(if(order_a7>0,user_id,null)) as repurchase_rate_a7
        ,count(if(order_a30>0 and order_a29_a0>0,user_id,null))/count(if(order_a30>0,user_id,null)) as repurchase_rate_a30
    from explode_data_${grass_region_without_quote}
    group by
         scenario_tag
);

--sql_divide_splitter--

INSERT INTO TABLE ${schema}.dws_sr_data_warehouse_platform_scenario_repurchase_30d PARTITION (grass_region = ${grass_region},local_date)
SELECT
     scenario_tag
    ,repurchase_rate_a7
    ,null  as repurchase_rate_a30

    ,date_sub(${local_date}, 7) as local_date
from result_${grass_region_without_quote}
where repurchase_rate_a7 is not null
union all
SELECT
     scenario_tag
    ,null as repurchase_rate_a7
    ,repurchase_rate_a30

    ,date_sub(${local_date}, 30) as local_date
from result_${grass_region_without_quote}
where repurchase_rate_a30 is not null
;
